import unittest
import lib_e4037293 as m


class Hidden(unittest.TestCase):
    def test_behavior(self):
        chain = ['1.0.0-alpha', '1.0.0-alpha.1', '1.0.0-alpha.beta', '1.0.0-beta', '1.0.0-beta.2', '1.0.0-beta.11', '1.0.0-rc.1', '1.0.0', '1.0.1', '1.2.0', '1.10.0', '2.0.0']
        for i, a in enumerate(chain):
            for j, b in enumerate(chain):
                self.assertEqual(m.compare(a, b), (i > j) - (i < j), (a, b))
        for a, b, want in [('4.2.8-2', '2.3.2-rc.10', 1), ('7.4.7-x.7', '0.10.11', 1), ('0.10.9-2', '10.5.6-beta', -1), ('2.2.11-alpha', '9.7.5-11', -1), ('1.11.1', '2.7.10-rc.10', -1), ('7.8.12-rc.1', '0.12.3-rc.10', 1), ('12.10.7', '5.10.11-11', 1), ('0.12.1-alpha', '7.3.2', -1), ('0.6.1', '0.4.9-11', 1), ('4.7.0', '0.10.1-beta', 1), ('12.4.10-alpha', '5.10.11-beta', 1), ('9.10.4-2', '9.10.4-2+build.5', 0), ('7.9.9', '7.9.9+build.5', 0), ('4.11.2-alpha', '10.5.2-rc.10', -1), ('1.8.8-rc.1', '4.1.0-11', -1), ('12.0.0', '2.6.12-rc.10', 1), ('8.1.12', '11.12.11-beta', -1), ('3.12.8-rc.1', '11.4.3', -1), ('9.8.10-x.7', '9.1.6-rc.10', 1), ('4.8.9-x.7', '0.11.0-beta', 1), ('5.6.9-2', '0.6.5-rc.10', 1), ('7.5.2-alpha', '1.0.4-11', 1), ('3.7.7-alpha', '5.0.0-rc.10', -1), ('2.1.2', '9.8.12-beta', -1), ('5.3.10-alpha', '5.3.10-alpha+build.5', 0), ('6.4.1', '10.4.0-11', -1), ('6.12.7', '4.8.9-beta', 1), ('4.0.5-alpha', '1.10.10-11', 1), ('4.0.9', '11.12.12-beta', -1), ('12.7.7-rc.1', '11.3.7-11', 1), ('11.9.7-alpha', '4.7.12-11', 1), ('1.3.10-2', '11.6.0-11', -1), ('0.11.9', '3.9.6-11', -1), ('4.3.0-alpha', '4.3.0-alpha+build.5', 0), ('3.9.8-2', '5.11.11-11', -1), ('1.4.3-x.7', '12.10.0-11', -1), ('11.6.5-2', '11.6.5-2+build.5', 0), ('6.6.11-alpha', '6.6.11-alpha+build.5', 0), ('7.0.3-rc.1', '9.9.1-beta', -1), ('12.7.9-rc.1', '12.7.9-rc.1+build.5', 0), ('9.4.6', '9.4.6+build.5', 0), ('2.3.3-x.7', '2.3.3-x.7+build.5', 0), ('1.1.8-alpha', '1.1.8-alpha+build.5', 0), ('12.6.9-2', '3.0.5-11', 1), ('8.3.4-rc.1', '3.1.2-rc.10', 1), ('10.8.5-alpha', '8.5.2-11', 1), ('3.6.8', '2.3.7', 1), ('0.5.10', '0.5.10+build.5', 0), ('11.6.7', '11.6.7+build.5', 0), ('5.6.3-alpha', '5.6.3-alpha+build.5', 0), ('3.12.7-rc.1', '2.5.6-beta', 1), ('10.2.2-alpha', '3.1.8-beta', 1), ('8.1.8-rc.1', '8.1.8-rc.1+build.5', 0), ('8.1.9-alpha', '9.7.12-11', -1), ('1.6.3-2', '10.1.10-rc.10', -1), ('10.4.12', '10.0.11', 1), ('7.5.6-alpha', '7.5.6-alpha+build.5', 0), ('5.7.8-2', '6.11.4-rc.10', -1), ('5.9.2', '6.4.0-11', -1), ('12.10.10-alpha', '12.1.4-rc.10', 1)]:
            self.assertEqual(m.compare(a, b), want, (a, b))
        for bad in ['1.0', '01.0.0', '1.0.0-', '1.0.0-01', 'v1.0.0', '', '1.0.0+']:
            with self.assertRaises(ValueError):
                m.compare(bad, '1.0.0')


if __name__ == "__main__":
    unittest.main()
